function syncAppIdentity(){document.title=appName();document.documentElement.lang=lang;}
let state=JSON.parse(localStorage.getItem('pb-active')||'null');if(state&&!state.type)state.type='x01';if(state?.type==='checkout'&&!state.limitType){state.limitType='rounds';state.maxRounds=Math.max(20,(state.results?.length||0)+1);delete state.attempts;delete state.targetAttempts;}
let route=state?routeForState():'home',setup={game:501,out:'DO'},highSetup=15,splitSetup='forward',rtwSetup={mode:'S',bull:false},checkoutSetup={mode:'pdc',limitType:'rounds',rounds:10,minutes:10,manual:[40],manualInput:'40'},challengeSetup='2',speedSetup='normal',fixSetup={mode:'custom',target:'20',minutes:15,workout:null},input='',err='',lastResult=null,checkoutTimer=null,checkoutClock=null,speedClock=null;
