function routeForState(){return state?.type==='high'?'highPlay':state?.type==='split'?'splitPlay':state?.type==='rtw'?'rtwPlay':state?.type==='bobs'?'bobsPlay':state?.type==='checkout'?'checkoutPlay':state?.type==='challenge'?'challengePlay':state?.type==='speed'?'speedPlay':state?.type==='fix'?'fixPlay':'play'}
function loadObj(k){try{return JSON.parse(localStorage.getItem(k)||'{}')}catch{return {}}}function saveObj(k,v){localStorage.setItem(k,JSON.stringify(v))}
function logSession(game,data={}){const a=loadObj('pb-session-log').items||[],item={at:new Date().toISOString(),game,...data};a.push(item);if(a.length>1000)a.splice(0,a.length-1000);saveObj('pb-session-log',{items:a})}
function recentSessions(game,days=30){const cut=Date.now()-days*86400000;return (loadObj('pb-session-log').items||[]).filter(x=>(!game||x.game===game)&&Date.parse(x.at)>=cut)}

function langToggle(){return `<div class=langswitch><button class='langbtn ${lang==='hr'?'on':''}' data-lang=hr>HR</button><button class='langbtn ${lang==='en'?'on':''}' data-lang=en>EN</button></div>`}
function home(){A.innerHTML=`<main class='app home'><div class=homehead><div><div class=brand>${lang==='hr'?'Pikado':'Darts'}<span>Bro</span></div><div class=sub>${t().trainer} <span class='app-version'>${APP_VERSION.replace(' TEST','')}</span></div></div>${langToggle()}</div><div class=grid>${state?`<button class='card red' data-a=resume><b>${t().resume}</b><small>${stateLabel()}</small></button>`:''}<button class=card data-a=x01><b>${t().x01}</b><small>301 / 501 / 701 / 901 / 1001</small></button><button class=card data-a=high><b>${t().high}</b><small>7 / 8 / 15 ${t().rounds.toLowerCase()}</small></button><button class=card data-a=split><b>${t().split}</b><small>15 → 20 + Bull</small></button><button class=card data-a=rtw><b>${t().rtw}</b><small>Singles / Doubles / Triples + Bull</small></button><button class=card data-a=checkout><b>${t().checkout}</b><small>PDC / Random / Manual / Crazy</small></button><button class=card data-a=challenge><b>🏁 Checkout Challenge</b><small>2 Dart · 3 Dart Finishes</small></button><button class=card data-a=speed><b>${t().speed}</b><small>Easy · Normal · Pro · King</small></button><button class=card data-a=bobs><b>${t().bobs}</b><small>D1 → D20 → Bull</small></button><button class=card data-a=fix><b>🔧 ${fixName()}</b><small>${lang==='hr'?'Ručno · Automatski · Moj trening':'Custom · Automatic · Practice for me'}</small></button><button class=card data-a=statsHome><b>▥ ${lang==='hr'?'Statistika':'Statistics'}</b><small>${lang==='hr'?'Svi treninzi · ukupni rezultati':'All training · lifetime results'}</small></button><button class=card data-a=dataHome><b>⇄ ${lang==='hr'?'Backup / Restore':'Backup / Restore'}</b><small>JSON · ${lang==='hr'?'lokalni podaci':'local data'}</small></button></div><div class=support-note>${lang==='hr'?'Ako ti PikadoBro pomaže, možeš autoru kupiti pivu ili whisk(e)y.':'If DartsBro helps your practice, you can buy the author a beer or whisk(e)y.'} <a href='https://revolut.me/@ivan50ba6' target='_blank' rel='noopener'>Revolut ❤️</a></div></main>`}
function stateLabel(){if(state.type==='high')return `High Score · ${state.maxRounds}`;if(state.type==='split')return state.direction==='back'?'Split Score Back':'Split Score';if(state.type==='rtw')return `Round the World · ${rtwModeName(state.mode)}`;if(state.type==='bobs')return `Bob's 27 · ${state.score}`;if(state.type==='checkout')return `Checkout · ${checkoutModeName(state.mode)}`;if(state.type==='challenge')return `Checkout Challenge · ${challengeProgress(state.mode).p.target}`;if(state.type==='speed')return `Speed Game · ${speedModeName(state.mode)}`;if(state.type==='fix')return `${fixName()} · ${fixTargetLabel(state.target)}`;return `${state.game} ${state.out}`}
