function setupView(){A.innerHTML=`<main class='app setup'>${topBar(t().x01.replace('🎯 ',''))}<label>${t().startScore}</label><div class=choices>${[301,501,701,901,1001].map(n=>`<button class='btn choice ${setup.game===n?'selected':''}' data-game=${n}>${n}</button>`).join('')}</div><label>${t().out}</label><div class=choices><button class='btn choice ${setup.out==='DO'?'selected':''}' data-out=DO>${t().doubleOut}</button><button class='btn choice ${setup.out==='MO'?'selected':''}' data-out=MO>${t().masterOut}</button></div><div class=maxnote>${t().maxRounds}: <strong>${limits[setup.game]}</strong></div><button class='btn red startbtn' data-a=start>${t().start}</button></main>`}
function highSetupView(){A.innerHTML=`<main class='app setup'>${topBar(t().high.replace('♛ ',''))}<label>${t().rounds}</label><div class=choices>${[7,8,15].map(n=>`<button class='btn choice ${highSetup===n?'selected':''}' data-high-rounds=${n}>${n}</button>`).join('')}</div><div class=maxnote>3 ${lang==='hr'?'strelice po rundi':'darts per round'}</div><button class='btn red startbtn' data-a=startHigh>${t().start}</button></main>`}
function splitSetupView(){A.innerHTML=`<main class='app setup'>${topBar(t().split.replace('◎ ',''))}<label>${lang==='hr'?'Smjer':'Direction'}</label><div class=choices><button class='btn choice ${splitSetup==='forward'?'selected':''}' data-split-dir=forward>${t().forward}</button><button class='btn choice ${splitSetup==='back'?'selected':''}' data-split-dir=back>${t().backward}</button></div><div class='splitpreview'>${splitSetup==='forward'?'15 → 16 → D → 17 → 18 → T → 19 → 20 → Bull':'Bull → 20 → 19 → T → 18 → 17 → D → 16 → 15'}</div><div class=maxnote>${lang==='hr'?'POČETNI SCORE':'STARTING SCORE'}: <strong>40</strong></div><button class='btn red startbtn' data-a=startSplit>${t().start}</button></main>`}

function rtwModeName(m){return m==='S'?(lang==='hr'?'SINGLOVI':'SINGLES'):m==='D'?(lang==='hr'?'DUPLI':'DOUBLES'):(lang==='hr'?'TRIPLI':'TRIPLES')}
function rtwBullLabel(mode=rtwSetup.mode){return mode==='S'?'Bull':mode==='D'?'DB':'Bull / DB'}
function rtwSetupView(){const bullLabel=rtwBullLabel();A.innerHTML=`<main class='app setup'>${topBar(t().rtw.replace('⊕ ',''))}<label>${lang==='hr'?'Prsten':'Ring'}</label><div class=choices>${['S','D','T'].map(m=>`<button class='btn choice ${rtwSetup.mode===m?'selected':''}' data-rtw-mode=${m}>${rtwModeName(m)}</button>`).join('')}</div><label>${lang==='hr'?'Završetak':'Finish'}</label><div class=choices><button class='btn choice ${!rtwSetup.bull?'selected':''}' data-rtw-bull=0>1 → 20</button><button class='btn choice ${rtwSetup.bull?'selected':''}' data-rtw-bull=1>1 → 20 → ${bullLabel}</button></div><div class=maxnote>${lang==='hr'?'Samo točan prsten vrijedi · MAX RUNDI: 40':'Exact ring only · MAX ROUNDS: 40'}</div><button class='btn red startbtn' data-a=startRtw>${t().start}</button></main>`}
function checkoutModeName(m){return m==='pdc'?'PDC':m==='random'?'RANDOM':m==='manual'?(lang==='hr'?'RUČNO':'MANUAL'):'CRAZY'}
function checkoutSetupView(){
 const roundOpts=[5,10,15,20,25,30,40,50],timeOpts=[5,10,15,20,25,30];
 A.innerHTML=`<main class='app setup checkout-setup'>${topBar(t().checkout.replace('◉ ',''))}
 <label>${lang==='hr'?'Način treninga':'Training mode'}</label>
 <div class=choices>${['pdc','random','manual','crazy'].map(m=>`<button class='btn choice ${checkoutSetup.mode===m?'selected':''}' data-checkout-mode=${m}>${checkoutModeName(m)}</button>`).join('')}</div>
 <label>${lang==='hr'?'Ograničenje treninga':'Training limit'}</label>
 <div class=choices><button class='btn choice ${checkoutSetup.limitType==='rounds'?'selected':''}' data-checkout-limit=rounds>${lang==='hr'?'RUNDE':'ROUNDS'}</button><button class='btn choice ${checkoutSetup.limitType==='time'?'selected':''}' data-checkout-limit=time>${lang==='hr'?'VRIJEME':'TIME'}</button></div>
 ${checkoutSetup.limitType==='rounds'?`<label>${lang==='hr'?'Broj rundi':'Number of rounds'}</label><select class=trainerselect data-checkout-rounds>${roundOpts.map(n=>`<option value=${n} ${checkoutSetup.rounds===n?'selected':''}>${n}</option>`).join('')}</select>`:`<label>${lang==='hr'?'Trajanje':'Trajanje'}</label><select class=trainerselect data-checkout-minutes>${timeOpts.map(n=>`<option value=${n} ${checkoutSetup.minutes===n?'selected':''}>${n} min</option>`).join('')}</select>`}
 ${checkoutSetup.mode==='manual'?`<label>${lang==='hr'?'Mete (2–170, odvojene zarezom)':'Targets (2–170, comma separated)'}</label><input class='manualtargets' data-manual-targets value='${esc(checkoutSetup.manualInput)}' inputmode=numeric placeholder='40, 32, 50'><div class=maxnote>${lang==='hr'?'Mete se vrte redom kroz cijeli trening':'Targets rotate in order for the whole session'}</div>`:''}
 <div class=splitpreview>${checkoutSetup.mode==='pdc'?'40 · 32 · 36 · 50 · 20 · 8 · 4 · 16 · 24':checkoutSetup.mode==='random'?(lang==='hr'?'Nasumično 2–40 · nova meta svaku rundu':'Random 2–40 · new target every round'):checkoutSetup.mode==='crazy'?(lang==='hr'?'Samo parni brojevi · promjena nakon nasumičnih 5–15 s':'Even numbers only · changes after a random 5–15 s'):(checkoutSetup.manual.join(' · ')||'—')}</div>
 <button class='btn red startbtn' data-a=startCheckout>${t().start}</button></main>`
}
function checkoutTargetsFor(mode){if(mode==='pdc')return [40,32,36,50,20,8,4,16,24];if(mode==='manual')return checkoutSetup.manual.length?checkoutSetup.manual:[40];return []}
function randomCheckoutTarget(max=40,avoid=null){let n;do n=2+Math.floor(Math.random()*(max-1));while(n===avoid);return n}
function randomEvenCheckoutTarget(avoid=null){const vals=[];for(let n=2;n<=40;n+=2)if(n!==avoid)vals.push(n);return vals[Math.floor(Math.random()*vals.length)]}
function currentCheckoutTarget(){if(state.mode==='random'||state.mode==='crazy')return state.currentTarget;return state.targets[state.results.length%state.targets.length]}
function fmtTime(ms){const total=Math.max(0,Math.ceil(ms/1000)),m=Math.floor(total/60),s=total%60;return `${m}:${String(s).padStart(2,'0')}`}
function clearCheckoutTimers(){clearTimeout(checkoutTimer);checkoutTimer=null;clearInterval(checkoutClock);checkoutClock=null}
function checkoutLimitReached(){return state.limitType==='rounds'&&state.results.length>=state.maxRounds}
function checkoutTimeExpired(){return state.limitType==='time'&&Date.now()>=state.deadline}
function startCheckoutClock(){clearInterval(checkoutClock);checkoutClock=null;if(!state||state.type!=='checkout'||state.limitType!=='time')return;const tick=()=>{if(!state||state.type!=='checkout'){clearInterval(checkoutClock);checkoutClock=null;return}const left=state.deadline-Date.now(),el=document.querySelector('[data-training-time]');if(el)el.textContent=fmtTime(left);if(left<=0){clearInterval(checkoutClock);checkoutClock=null;finishCheckout('time')}};tick();if(state&&state.type==='checkout')checkoutClock=setInterval(tick,250)}
function checkoutPlay(){
 clearTimeout(checkoutTimer);checkoutTimer=null;
 if(checkoutTimeExpired())return finishCheckout('time');
 if(checkoutLimitReached())return finishCheckout('rounds');
 const target=currentCheckoutTarget(),roundNo=state.results.length+1,last=state.results.slice(-3),limitInfo=state.limitType==='rounds'?`${t().round} ${roundNo} / ${state.maxRounds}`:`${t().round} ${roundNo} · <span data-training-time>${fmtTime(state.deadline-Date.now())}</span>`;
 const crazyLocked=false;
 A.innerHTML=`<main class='app trainer-screen checkout-game ${state.flash?'flash':''}' data-game-surface><div class=top><div class=title>Checkout · ${checkoutModeName(state.mode)}</div><div class=roundinfo>${limitInfo}</div></div><div class=targetlabel>${t().target}</div><div class='score targetscore checkout-target'>${target}</div>${state.mode==='crazy'?'':`<div class=targetlabel>${lang==='hr'?'Jesi li izašao u ovoj rundi?':'Did you check out this round?'}</div>`}<div class='checkout-actions'><button class='markbtn miss' data-checkout-result=miss ${crazyLocked?'disabled':''}>${lang==='hr'?'PROMAŠAJ':'MISS'}</button><button class='markbtn hit' data-checkout-result=hit ${crazyLocked?'disabled':''}>${lang==='hr'?'IZLAZ':'HIT'}</button></div><div class=visits>${[0,1,2].map((_,i)=>`<div class=visit>${last[i]?`${last[i].target} · ${last[i].hit?'✓':'×'}`:''}</div>`).join('')}</div><button class='btn undobtn' data-a=undo ${state.canUndo?'':'disabled'}>${t().undo}</button><div class=gesturehint>••</div></main>`;
 startCheckoutClock();
 if(state&&state.mode==='crazy')scheduleCrazy()
}
function scheduleCrazy(){
 clearTimeout(checkoutTimer);checkoutTimer=null;
 if(!state||state.type!=='checkout'||state.mode!=='crazy')return;
 if(!state.nextChange)state.nextChange=Date.now()+5000+Math.floor(Math.random()*10001);
 const wait=Math.max(0,state.nextChange-Date.now());
 checkoutTimer=setTimeout(()=>{if(!state||state.type!=='checkout'||state.mode!=='crazy'||checkoutTimeExpired())return;state.currentTarget=randomEvenCheckoutTarget(state.currentTarget);state.ready=true;state.flash=true;state.changedAt=Date.now();state.nextChange=null;save();beep();checkoutPlay();setTimeout(()=>{if(state&&state.type==='checkout'){state.flash=false;save();document.querySelector('.checkout-game')?.classList.remove('flash')}},450)},wait)
}
function beep(){try{const C=window.AudioContext||window.webkitAudioContext,c=new C(),o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);o.frequency.value=880;g.gain.value=.06;o.start();o.stop(c.currentTime+.11);o.onended=()=>{try{c.close()}catch{}}}catch{}}
function submitCheckoutResult(hit){
 if(!state||state.type!=='checkout'||checkoutTimeExpired())return finishCheckout('time');
  const target=currentCheckoutTarget(),r={target,hit,round:state.results.length+1,reaction:state.mode==='crazy'?Date.now()-state.changedAt:null};
 state.results.push(r);state.canUndo=true;
 if(state.mode==='random')state.currentTarget=randomCheckoutTarget(40,target);
 if(state.mode==='crazy'){state.currentTarget=randomEvenCheckoutTarget(target);state.ready=true;state.flash=false;state.changedAt=Date.now();state.nextChange=Date.now()+5000+Math.floor(Math.random()*10001)}
 save();
 if(checkoutLimitReached())return finishCheckout('rounds');
 checkoutPlay()
}
function finishCheckout(reason='done'){
 if(!state||state.type!=='checkout')return;clearCheckoutTimers();
 const s=structuredClone(state),hits=s.results.filter(r=>r.hit).length,total=s.results.length,pct=total?hits/total*100:0,elapsed=Math.max(1,Math.min(Date.now()-s.started,s.limitType==='time'?s.minutes*60000:Date.now()-s.started)),rpm=total/(elapsed/60000);
 const all=loadObj('pb-checkout-stats'),k=s.mode,x=all[k]||{sessions:0,hits:0,attempts:0,rounds:0,target:{}};x.sessions++;x.hits+=hits;x.attempts+=total;x.rounds=(x.rounds||0)+total;
 for(const r of s.results){const q=String(r.target);x.target[q]=x.target[q]||{attempts:0,hits:0};x.target[q].attempts++;if(r.hit)x.target[q].hits++}all[k]=x;saveObj('pb-checkout-stats',all);
 state=null;save();route='home';home();
 const timeStat=s.limitType==='time'?`<div><b>${fmtTime(elapsed)}</b><small>${lang==='hr'?'VRIJEME':'TIME'}</small></div>`:`<div><b>${total}</b><small>${lang==='hr'?'RUNDI':'ROUNDS'}</small></div>`;
 modal(`<h2>${t().completed}</h2><div class=resultscore>${hits} / ${total}</div><div class=statgrid><div><b>${pct.toFixed(1)}%</b><small>CHECKOUT</small></div><div><b>${hits}</b><small>${lang==='hr'?'IZLAZA':'HITS'}</small></div><div><b>${total-hits}</b><small>${lang==='hr'?'PROMAŠAJA':'MISSES'}</small></div>${timeStat}<div><b>${rpm.toFixed(1)}</b><small>${lang==='hr'?'RUNDI / MIN':'ROUNDS / MIN'}</small></div></div><div class=modalactions><button class='btn red' data-a=playCheckoutAgain data-mode=${s.mode} data-limit=${s.limitType} data-rounds=${s.maxRounds||checkoutSetup.rounds} data-minutes=${s.minutes||checkoutSetup.minutes}>${t().playAgain}</button><button class='btn' data-a=home>${t().home}</button></div>`)
}
function startCheckout(mode=checkoutSetup.mode,limitType=checkoutSetup.limitType,rounds=checkoutSetup.rounds,minutes=checkoutSetup.minutes,manualTargets=null){
 clearCheckoutTimers();const targets=manualTargets||(mode==='manual'?(checkoutSetup.manual.length?checkoutSetup.manual:[40]):checkoutTargetsFor(mode)),now=Date.now();
 state={type:'checkout',mode,limitType,maxRounds:limitType==='rounds'?+rounds:null,minutes:limitType==='time'?+minutes:null,deadline:limitType==='time'?now+(+minutes*60000):null,targets,targetIndex:0,currentTarget:mode==='random'?randomCheckoutTarget(40):mode==='crazy'?randomEvenCheckoutTarget():null,results:[],canUndo:false,ready:true,flash:false,nextChange:null,changedAt:mode==='crazy'?now:null,started:now};
 save();route='checkoutPlay';render()
}

function rtwBullTarget(mode=state.mode){return mode==='S'?'BULL':mode==='D'?'DB':'BULL/DB'}
function rtwTargets(){return [...Array(20)].map((_,i)=>i+1).concat(state.bull?[rtwBullTarget()]:[])}
function rtwTargetIndex(){return state.visits.reduce((n,v)=>n+(v.hits>0?1:0),0)}
function rtwPlay(){const targets=rtwTargets(),idx=rtwTargetIndex();if(idx>=targets.length)return finishRtw();const target=targets[idx],last=state.visits.slice(-3),isBull=typeof target==='string',targetText=target==='BULL'?'BULL (25)':target==='DB'?'DB (50)':target==='BULL/DB'?'BULL / DB':target,help=isBull?(state.mode==='S'?(lang==='hr'?'Koliko strelica je pogodilo Bull 25?':'How many darts hit Bull 25?'):state.mode==='D'?(lang==='hr'?'Koliko strelica je pogodilo DB 50?':'How many darts hit DB 50?'):(lang==='hr'?'Koliko strelica je pogodilo Bull 25 ili DB 50?':'How many darts hit Bull 25 or DB 50?')):(lang==='hr'?'Koliko od 3 strelice je pogodilo točan prsten?':'How many of 3 darts hit the exact ring?');A.innerHTML=`<main class='app trainer-screen rtw-game' data-game-surface><div class=top><div class=title>Round the World · ${rtwModeName(state.mode)}</div><div class=roundinfo>${t().round} ${Math.min(state.visits.length+1,40)} / 40</div></div><div class=targetlabel>${t().target}</div><div class='score targetscore'>${targetText}</div><div class=targetlabel>${help}</div><div class='hit-four'>${[0,1,2,3].map(n=>`<button class='markbtn ${n===0?'miss':''}' data-rtw-hits=${n}>${n}</button>`).join('')}</div><div class=visits>${[0,1,2].map((_,i)=>`<div class=visit>${last[i]?`${last[i].target} · ${last[i].hits}/3`:''}</div>`).join('')}</div><button class='btn undobtn' data-a=undo ${state.canUndo?'':'disabled'}>${t().undo}</button><div class=gesturehint>••</div></main>`}
function submitRtw(hits){const targets=rtwTargets(),idx=rtwTargetIndex(),target=targets[idx];state.visits.push({target,hits:+hits});state.canUndo=true;save();if(+hits>0&&idx+1>=targets.length)return finishRtw(true);if(state.visits.length>=40)return finishRtw(false);rtwPlay()}
function finishRtw(completed=true){const s=structuredClone(state),hits=s.visits.reduce((a,v)=>a+v.hits,0),darts=s.visits.length*3,r={mode:s.mode,bull:s.bull,hits,darts,pct:darts?hits/darts*100:0,perfect:s.visits.filter(v=>v.hits===3).length,zero:s.visits.filter(v=>v.hits===0).length,visits:s.visits};const all=loadObj('pb-rtw-stats'),k=`${s.mode}-${s.bull?'DB':'20'}`,x=all[k]||{games:0,hits:0,darts:0,best:0,perfect:0,zero:0,target:{}};x.games++;x.hits+=hits;x.darts+=darts;x.best=Math.max(x.best,hits);x.perfect+=r.perfect;x.zero+=r.zero;for(const v of s.visits){const q=String(v.target);x.target[q]=x.target[q]||{rounds:0,hits:0};x.target[q].rounds++;x.target[q].hits+=v.hits}all[k]=x;saveObj('pb-rtw-stats',all);r.lifetime=x;state=null;save();route='home';home();modal(`<h2>${completed?t().completed:t().failed}</h2><div class=resultscore>${hits} / ${darts}</div><div class=statgrid><div><b>${r.pct.toFixed(1)}%</b><small>${lang==='hr'?'POGODAKA':'HIT RATE'}</small></div><div><b>${r.perfect}</b><small>3 / 3</small></div><div><b>${r.zero}</b><small>0 / 3</small></div><div><b>${x.best}</b><small>${lang==='hr'?'OSOBNI REKORD':'PERSONAL BEST'}</small></div></div><div class=modalactions><button class='btn red' data-a=playRtwAgain data-mode=${s.mode} data-bull=${s.bull?1:0}>${t().playAgain}</button><button class='btn' data-a=home>${t().home}</button></div>`)}
function bobsPlay(){const idx=state.visits.length;if(idx>=21)return finishBobs(true);const n=idx+1,target=n<=20?`D${n}`:'BULL',last=state.visits.slice(-3);A.innerHTML=`<main class='app trainer-screen bobs-game' data-game-surface><div class=top><div class=title>Bob's 27</div><div class=roundinfo>${idx+1} / 21</div></div><div class=targetlabel>${t().target}</div><div class='score targetscore'>${target}</div><div class='split-current'>${t().total}: <b>${state.score}</b></div><div class=targetlabel>${lang==='hr'?'Pogodaka s 3 strelice':'Hits with 3 darts'}</div><div class='hit-four'>${[0,1,2,3].map(n=>`<button class='markbtn ${n===0?'miss':''}' data-bobs-hits=${n}>${n}</button>`).join('')}</div><div class=visits>${[0,1,2].map((_,i)=>`<div class=visit>${last[i]?`${last[i].target} · ${last[i].hits}/3`:''}</div>`).join('')}</div><button class='btn undobtn' data-a=undo ${state.canUndo?'':'disabled'}>${t().undo}</button><div class=gesturehint>••</div></main>`}
function submitBobs(hits){const idx=state.visits.length,n=idx+1,value=n<=20?n*2:50,target=n<=20?`D${n}`:'BULL',before=state.score,delta=+hits?+hits*value:-value;state.score+=delta;state.visits.push({target,hits:+hits,value,before,after:state.score,delta});state.canUndo=true;save();if(state.score<=0)return finishBobs(false);if(state.visits.length>=21)return finishBobs(true);bobsPlay()}
function finishBobs(completed){const s=structuredClone(state),hits=s.visits.reduce((a,v)=>a+v.hits,0),darts=s.visits.length*3,r={score:s.score,completed,hits,darts,pct:darts?hits/darts*100:0,highest:s.visits.at(-1)?.target||'—',visits:s.visits};const all=loadObj('pb-bobs-stats'),x=all.main||{games:0,best:null,completed:0,hits:0,darts:0,target:{}};x.games++;x.best=x.best===null?r.score:Math.max(x.best,r.score);if(completed)x.completed++;x.hits+=hits;x.darts+=darts;for(const v of s.visits){x.target[v.target]=x.target[v.target]||{rounds:0,hits:0};x.target[v.target].rounds++;x.target[v.target].hits+=v.hits}all.main=x;saveObj('pb-bobs-stats',all);state=null;save();route='home';home();modal(`<h2>${completed?t().completed:(lang==='hr'?'KRAJ — SCORE ≤ 0':'GAME OVER — SCORE ≤ 0')}</h2><div class=resultscore>${r.score}</div><div class=statgrid><div><b>${r.pct.toFixed(1)}%</b><small>${lang==='hr'?'POGODAKA':'HIT RATE'}</small></div><div><b>${r.highest}</b><small>${lang==='hr'?'NAJVIŠA META':'HIGHEST TARGET'}</small></div><div><b>${x.best}</b><small>${lang==='hr'?'OSOBNI REKORD':'PERSONAL BEST'}</small></div><div><b>${completed?'DA':'NE'}</b><small>${lang==='hr'?'ZAVRŠENO':'COMPLETED'}</small></div></div><div class=modalactions><button class='btn red' data-a=playBobsAgain>${t().playAgain}</button><button class='btn' data-a=home>${t().home}</button></div>`)}

const challengeDarts=[];
for(let n=1;n<=20;n++){challengeDarts.push({v:n,l:`S${n}`,k:'S'});challengeDarts.push({v:n*2,l:`D${n}`,k:'D'});challengeDarts.push({v:n*3,l:`T${n}`,k:'T'})}
