function routeRank(r){const pref={'D20':0,'D16':1,'D18':2,'D12':3,'D10':4,'D8':5,'D4':6,'D2':7,'BULL':8};let x=r.length*100+(pref[r.at(-1).l]??20);for(let i=0;i<r.length-1;i++)x+=(r[i].k==='S'?0:r[i].k==='T'?2:4)+i;return x}
