function routeObj(label){const v=label==='BULL'?50:label==='25'||label==='S25'?25:+label.slice(1)*(label[0]==='T'?3:label[0]==='D'?2:1);return {v,l:label,k:label==='BULL'||label[0]==='D'?'D':label[0]==='T'?'T':'S'}}
function recommendedRoutes(score,maxDarts){const std=standardCheckoutRoutes[score];if(std){const r=std.split(' ').map(routeObj);if(r.length<=maxDarts)return [r]}return checkoutRoutes(score,maxDarts).slice(0,2)}
function checkoutRoutes(score,maxDarts){const ck=`${score}-${maxDarts}`;if(challengeRouteCache.has(ck))return challengeRouteCache.get(ck);const out=[];function walk(left,path){if(path.length>=maxDarts)return;for(const d of challengeFinishers)if(d.v===left)out.push([...path,d]);if(path.length+1>=maxDarts)return;for(const d of challengeDarts){if(d.v>=left)continue;walk(left-d.v,[...path,d])}}walk(score,[]);const seen=new Set();const result=out.sort((a,b)=>routeRank(a)-routeRank(b)).filter(r=>{const k=r.map(x=>x.l).join('|');if(seen.has(k))return false;seen.add(k);return true}).slice(0,3);challengeRouteCache.set(ck,result);return result}
